    java_last_garbage_collection_LastGcInfo_memoryUsageAfterGc_Code_Cache_init: 'GC 后 Code Cache 空间初始内存量',
    mysql_performance_schema_socket_instances_lost: '无法创建多少个套接字工具实例',
